from z3 import *

def solve():
    V = 18
    E = [[Bool(f"e_{i}_{j}") if i < j else Bool(f"e_{j}_{i}") for j in range(V)] for i in range(V)]

    s = Solver()

    # Number of edges >= 27
    s.add(Sum([If(E[i][j], 1, 0) for i in range(V) for j in range(i+1, V)]) >= 27)

    # Girth >= 7
    # No cycles of length 3
    for i in range(V):
        for j in range(i+1, V):
            for k in range(j+1, V):
                s.add(Not(And(E[i][j], E[j][k], E[i][k])))

    # No cycles of length 4
    for i in range(V):
        for j in range(i+1, V):
            for k in range(j+1, V):
                for l in range(k+1, V):
                    # 3 possible 4-cycles on 4 vertices
                    s.add(Not(And(E[i][j], E[j][k], E[k][l], E[i][l])))
                    s.add(Not(And(E[i][j], E[j][l], E[l][k], E[i][k])))
                    s.add(Not(And(E[i][k], E[k][j], E[j][l], E[i][l])))

    # No cycles of length 5
    import itertools
    for p in itertools.combinations(range(V), 5):
        # 12 possible 5-cycles on 5 vertices
        # A 5-cycle is defined by a permutation of the 5 vertices, modulo cyclic shifts and reversal.
        # 5! / (5 * 2) = 12
        for perm in itertools.permutations(p):
            if perm[0] == p[0] and perm[1] < perm[-1]:
                s.add(Not(And(E[perm[0]][perm[1]], E[perm[1]][perm[2]], E[perm[2]][perm[3]], E[perm[3]][perm[4]], E[perm[4]][perm[0]])))

    # No cycles of length 6
    for p in itertools.combinations(range(V), 6):
        for perm in itertools.permutations(p):
            if perm[0] == p[0] and perm[1] < perm[-1]:
                s.add(Not(And(E[perm[0]][perm[1]], E[perm[1]][perm[2]], E[perm[2]][perm[3]], E[perm[3]][perm[4]], E[perm[4]][perm[5]], E[perm[5]][perm[0]])))

    # 4-colorable
    C = [Int(f"c_{i}") for i in range(V)]
    for i in range(V):
        s.add(C[i] >= 0, C[i] <= 3)
    for i in range(V):
        for j in range(i+1, V):
            s.add(Implies(E[i][j], C[i] != C[j]))

    print("Solving...")
    if s.check() == sat:
        m = s.model()
        edges = []
        for i in range(V):
            for j in range(i+1, V):
                if is_true(m[E[i][j]]):
                    edges.append((i, j))
        print("SAT")
        print(edges)
    else:
        print("UNSAT")

solve()

from pysat.solvers import Glucose4
from pysat.card import CardEnc
from itertools import combinations, permutations

def solve_sat(n, target_edges):
    solver = Glucose4()

    # Variables for edges
    # e_{i,j} for i < j
    edge_vars = {}
    var_idx = 1
    for i in range(n):
        for j in range(i+1, n):
            edge_vars[(i, j)] = var_idx
            var_idx += 1

    def var(i, j):
        if i > j:
            i, j = j, i
        return edge_vars[(i, j)]

    # Girth >= 7 means no cycles of length 3, 4, 5, 6
    # Length 3
    for i, j, k in combinations(range(n), 3):
        solver.add_clause([-var(i,j), -var(j,k), -var(i,k)])

    # Length 4
    for p in combinations(range(n), 4):
        i, j, k, l = p
        solver.add_clause([-var(i,j), -var(j,k), -var(k,l), -var(i,l)])
        solver.add_clause([-var(i,j), -var(j,l), -var(l,k), -var(i,k)])
        solver.add_clause([-var(i,k), -var(k,j), -var(j,l), -var(i,l)])

    # Length 5
    for p in combinations(range(n), 5):
        for perm in permutations(p):
            if perm[0] == p[0] and perm[1] < perm[-1]:
                solver.add_clause([-var(perm[0], perm[1]), -var(perm[1], perm[2]), 
                                   -var(perm[2], perm[3]), -var(perm[3], perm[4]), 
                                   -var(perm[4], perm[0])])

    # Length 6
    for p in combinations(range(n), 6):
        for perm in permutations(p):
            if perm[0] == p[0] and perm[1] < perm[-1]:
                solver.add_clause([-var(perm[0], perm[1]), -var(perm[1], perm[2]), 
                                   -var(perm[2], perm[3]), -var(perm[3], perm[4]), 
                                   -var(perm[4], perm[5]), -var(perm[5], perm[0])])

    # At least target_edges
    lits = [var(i, j) for i in range(n) for j in range(i+1, n)]
    cnf = CardEnc.atleast(lits, bound=target_edges, top_id=var_idx)
    for clause in cnf.clauses:
        solver.add_clause(clause)

    print("Solving...")
    if solver.solve():
        print("SAT")
        model = solver.get_model()
        edges = []
        for i in range(n):
            for j in range(i+1, n):
                if model[var(i, j) - 1] > 0:
                    edges.append((i, j))
        print(edges)
        return True
    else:
        print("UNSAT")
        return False

